use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-descriptor-chunks176";const P:&str="/home/ubuntu/src/zopro-perf-work/g2-denominator-tree176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn sha(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn registry_packages(p:impl AsRef<Path>)->BTreeMap<String,String>{let s=fs::read_to_string(p).unwrap();let mut out=BTreeMap::new();for block in s.split("[[package]]").skip(1){let fields=block.lines().filter_map(|l|l.split_once(" = ")).map(|(a,b)|(a,b.trim_matches('"'))).collect::<BTreeMap<_,_>>();if fields.get("source").is_some_and(|s|s.starts_with("registry+")){out.insert(fields["name"].into(),format!("{}:{}",fields["version"],fields["checksum"]));}}out}
fn main(){assert!(!r("reference-audit.json").exists());assert!(!r("control-bin").exists());let pins=read(format!("{P}/pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(sha(p),h.as_str().unwrap(),"prior pin {p}");}assert_eq!(sha(format!("{P}/control-bin")),"f07229ce665cf61c972037a27752bb53cce8c5dd58be0c71d8776434c961064b");let manifest=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let mut exact=0;for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){let original=fs::read(Path::new(Z).join(p)).unwrap();assert_eq!(sha(Path::new(Z).join(p)),h.as_str().unwrap());let old=fs::read(Path::new(P).join("control/source").join(p)).unwrap();assert!(old.starts_with(&original));if old==original{exact+=1;}assert_eq!(sha(Path::new(P).join("control/source").join(p)),pins[Path::new(P).join("control/source").join(p).display().to_string()]);}assert_eq!(exact,174);
 let driver=fs::read(format!("{P}/driver.rs")).unwrap();assert_eq!(driver,fs::read(r("driver/src/main.rs")).unwrap());assert_eq!(driver,fs::read(format!("{P}/control/src/main.rs")).unwrap());let g1=fs::read(format!("{P}/g1-caller.rs")).unwrap();assert_eq!(g1,fs::read(r("g1-caller.rs")).unwrap());let mut g2=fs::read_to_string(r("g2-caller.rs")).unwrap();let audit=read(r("source-audit.json"));for e in audit["G2_caller_edits"].as_array().unwrap().iter().rev(){let from=e[1].as_str().unwrap();assert_eq!(g2.matches(from).count(),1);g2=g2.replacen(from,e[0].as_str().unwrap(),1);}assert_eq!(g2,fs::read_to_string(format!("{P}/g2-caller.rs")).unwrap());let oldlog=fs::read_to_string(format!("{P}/build-control.log")).unwrap();let oldline=oldlog.lines().find(|l|l.contains("Running")&&l.contains("--crate-name zopro_denominator_tree_control")).unwrap();for f in["-C opt-level=3","-C lto -C","-C codegen-units=1","-C target-cpu=native"]{assert!(oldline.contains(f));}assert!(!oldline.contains("--cfg zopro_denominator_tree"));let old_packages=registry_packages(format!("{P}/control/Cargo.lock"));let new_packages=registry_packages(r("driver/Cargo.lock"));
 let mut ids=read(r("identities.json"));let off=ids["OFF"].clone();assert_eq!(sha(off["binary"].as_str().unwrap()),off["binary_sha256"]);assert_eq!(ids["OFF"],ids["ON"]);fs::copy(format!("{P}/control-bin"),r("control-bin")).unwrap();assert_eq!(sha(r("control-bin")),sha(format!("{P}/control-bin")));ids["frozen"]=json!({"binary":r("control-bin"),"binary_sha256":sha(r("control-bin")),"actual_rustc":oldline,"original_binary":format!("{P}/control-bin"),"kind":"pre-existing source176 ordinary kernel caller; not accepted SDK"});fs::write(r("identities.json"),serde_json::to_vec_pretty(&ids).unwrap()).unwrap();let result=json!({"passed":true,"parent_pin_entries_checked":pins.as_object().unwrap().len(),"original_source176_unchanged":true,"frozen_originals_exact":exact,"frozen_originals_append_only":2,"all_frozen176_originals_prefix_recovered":true,"matching_driver_G1_exact":true,"G2_fixture_inverse_recovered":true,"unchanged_field_and_original_G2_apply":true,"both_consumers_optimized_native_fatLTO_oneCGU":true,"registry_packages_equal":old_packages==new_packages,"old_registry_packages":old_packages,"new_registry_packages":new_packages,"frozen_sha256":ids["frozen"]["binary_sha256"],"fresh_sha256":ids["OFF"]["binary_sha256"],"no_queries_or_captures":true});fs::write(r("reference-audit.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{}",json!({"passed":true,"pins":result["parent_pin_entries_checked"],"registry_packages_equal":result["registry_packages_equal"],"frozen_sha256":result["frozen_sha256"]}));}
